import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    static String toBinary(int n) {
        if (n < 2) return String.valueOf(n);
        return toBinary(n / 2) + (n % 2);
    }

    static final Map<String, Integer> paths = new HashMap<>();

    static int countPaths(int rows, int cols) {
        if (rows == 1 || cols == 1) return 1;
        String key = rows + "," + cols;
        Integer known = paths.get(key);
        if (known != null) return known;
        int result = countPaths(rows - 1, cols) + countPaths(rows, cols - 1);
        paths.put(key, result);
        return result;
    }

    static List<String> permutations(String s) {
        List<String> found = new ArrayList<>();
        permute("", s, found);
        Collections.sort(found);
        return found;
    }

    static void permute(String prefix, String rest, List<String> found) {
        if (rest.isEmpty()) {
            if (!found.contains(prefix)) found.add(prefix);
            return;
        }
        permuteFrom(prefix, rest, 0, found);
    }

    static void permuteFrom(String prefix, String rest, int i, List<String> found) {
        if (i == rest.length()) return;
        permute(prefix + rest.charAt(i), rest.substring(0, i) + rest.substring(i + 1), found);
        permuteFrom(prefix, rest, i + 1, found);
    }

    static List<String> hanoi(int n, char from, char to, char via) {
        List<String> moves = new ArrayList<>();
        move(n, from, to, via, moves);
        return moves;
    }

    static void move(int n, char from, char to, char via, List<String> moves) {
        if (n == 0) return;
        move(n - 1, from, via, to, moves);
        moves.add(from + "->" + to);
        move(n - 1, via, to, from, moves);
    }
}

unitTests:
test("binary", () -> {
    checkEq(Solution.toBinary(10), "1010");
    checkEq(Solution.toBinary(0), "0");
    checkEq(Solution.toBinary(1), "1");
    checkEq(Solution.toBinary(255), "11111111");
});

test("grid paths", () -> {
    checkEq(Solution.countPaths(1, 5), 1);
    checkEq(Solution.countPaths(3, 3), 6);
    checkEq(Solution.countPaths(3, 7), 28);
    checkEq(Solution.countPaths(16, 16), 155117520);
});

test("permutations", () -> {
    checkEq(Solution.permutations("abc"), List.of("abc", "acb", "bac", "bca", "cab", "cba"));
    checkEq(Solution.permutations("aba"), List.of("aab", "aba", "baa"));
    checkEq(Solution.permutations(""), List.of(""));
    checkEq(Solution.permutations("abcdef").size(), 720);
});

test("towers of Hanoi", () -> {
    checkEq(Solution.hanoi(1, 'A', 'C', 'B'), List.of("A->C"));
    checkEq(Solution.hanoi(2, 'A', 'C', 'B'), List.of("A->B", "A->C", "B->C"));
    checkEq(Solution.hanoi(10, 'A', 'C', 'B').size(), 1023);
});

